{"path": "rest_api.py", "content": "import json


class RestAPI:
    def __init__(self, database=None):
        self.users = {}
        for user in (database or {}).get("users", []):
            self.users[user["name"]] = {
                "name": user["name"],
                "owes": dict(user.get("owes", {})),
                "owed_by": dict(user.get("owed_by", {})),
            }

    def _view(self, name):
        user = self.users[name]
        balance = sum(user["owed_by"].values()) - sum(user["owes"].values())
        return {
            "name": name,
            "owes": dict(user["owes"]),
            "owed_by": dict(user["owed_by"]),
            "balance": balance,
        }

    def get(self, url, payload=None):
        if url == "/users":
            names = sorted(self.users)
            if payload:
                wanted = set(json.loads(payload).get("users", []))
                names = [n for n in names if n in wanted]
            return json.dumps({"users": [self._view(n) for n in names]})
        return json.dumps({"error": "not found"})

    def post(self, url, payload=None):
        data = json.loads(payload) if payload else {}
        if url == "/add":
            name = data["user"]
            if name not in self.users:
                self.users[name] = {"name": name, "owes": {}, "owed_by": {}}
            return json.dumps(self._view(name))
        if url == "/iou":
            lender, borrower = data["lender"], data["borrower"]
            amount = data["amount"]
            lu, bu = self.users[lender], self.users[borrower]
            # net against what lender already owes borrower
            net = lu["owes"].pop(borrower, 0) - amount
            bu["owed_by"].pop(lender, None)
            lu["owed_by"].pop(borrower, None)
            bu["owes"].pop(lender, None)
            if net > 0:
                lu["owes"][borrower] = net
                bu["owed_by"][lender] = net
            elif net < 0:
                prior = 0
                lu["owed_by"][borrower] = -net
                bu["owes"][lender] = -net
            return json.dumps(
                {"users": [self._view(n) for n in sorted({lender, borrower})]}
            )
        return json.dumps({"error": "not found"})
"}
